using System;

namespace StdbModule;

public static partial class HindiQuotes
{
    public static class रमवलसशरम
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "कला की विषयवस्तु न वेदान्तियों का ब्रह्म है, न हेगल का निरपेक्ष विचार। मनुष्य का इन्द्रियबोध, उसके भाव उसके विचार, उसका सौन्दर्यबोध कला की विषयवस्तु है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "साहित्य के सभी तत्त्व समान रूप से परिवर्तनशील नहीं है, इन्द्रियबोध की अपेक्षा भाव और भावों की अपेक्षा विचार अधिक परिवर्तनशील है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "साहित्य का शिल्प, उसके विभिन्न रूप, सामाजिक विकास से ही सम्भव हुए हैं।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "निर्णायक भूमिका हमेशा विषयवस्तु की ही होती है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "जब दोनों में इतना घनिष्ठ सम्बन्ध है, तब विषय-वस्तु की चर्चा भी प्रयाप्त हो सकती है, चर्चा के लिए भाषा ही क्यों चुनी गई।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "साहित्य शुद्ध विचारधारा का रूप नहीं हैं, उसका भावों और इंद्रियबोध से घनिष्ठ सम्बन्ध है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "यह आवश्यक नहीं कि शोषक वर्ग ने जिन नैतिक अथवा कलात्मक मूल्यों का निर्माण किया है वे सभी शोषण-मुक्त वर्ग के लिए अनुपयोगी हों", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "शुक्लजी की आलोचना गम्भीर है, इसलिए कि उसका आधार वस्तुवादी दृष्टिकोण है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "विरोधी लगने वाली वस्तुओं का सामंजस्य पहचानना, उन्हें गतिशील और विकासमान देखना, संसार के विभिन्न भौतिक और मानसिक व्यापारों का परस्पर सम्बन्ध स्थापित करके उनका अध्ययन करना इस पद्धति की विशेषताएँ हैं।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "भारतेन्दु युग का साहित्य हिन्दी-भाषी जनता का जातीय साहित्य है, वह हमारे जातीय नवजागरण का साहित्य है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "भारतेन्दु युग की जिन्दादिली, उसके व्यंग्य और हास्य, उसके सरल-सरस गद्य और लोक-संस्कृति से उसकी निकटता से सभी परिचित हैं।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "लेकिन उसके साहित्य की जड़ें इसी धरती में हैं और ऊपर बताई हुई उसकी जातीय विशेषताएँ उसकी अपनी हैं, मौलिक हैं।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "हिन्दी में नवीन चेतना किन व्यक्तियों और संस्थानों के माध्यम से विकसित हो रही थी।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "यह भारतेन्दु-युग की बहुत बड़ी विशेषता थी।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "जो नवजागरण 1857 के स्वाधीनता संग्राम से आरम्भ हुआ, वह भारतेन्दु युग में और व्यापक बना, उसकी साम्राज्य-विरोधी, सामन्त-विरोधी प्रवृत्तियाँ द्विवेदी युग में और पुष्ट हुई।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "साहित्य में जो रीति-विरोधी क्रान्ति शुरू हुई उसका पहला चरण है द्विवेदी युग और उसी का विकास छायावाद और प्रगतिवाद में होता है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "पूर्व तक हिन्दी में ऐसी हवा बह रही थी कि लोग पं. रामचन्द्र शुक्ल के विचारों का विरोध करना अपनी आलोचनात्मक प्रतिभा का परिचय देना समझते थे।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "दुर्भाग्यवश जो लोग अपने को शुक्लानुवर्ती कहते थे और शुक्लजी के विचारों का विरोध करने वालों का विरोध करते थे, वे शुक्लजी की साहित्य-सेवा की महत्ता को प्रकट करने में असमर्थ थे।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "हिन्दी साहित्य में शुक्लजी का वही महत्त्व है जो उपन्यासकार प्रेमचन्द या कवि निराला का।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उन्होंने आलोचना के माध्यम से उसी सामन्ती संस्कृति का विरोध किया जिसका उपन्यास और कविता के माध्यम से प्रेमचन्द और निराला ने।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "शुक्लजी न तो भारत के रूढ़िवाद को स्वीकार किया, न पश्चिम के व्यक्तिवाद को।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उनका यह कार्य हर देशप्रेमी और जनवादी लेखक तथा पाठक के लिए दिलचस्प होना चाहिए।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उन्होंने हिन्दी की सैद्धान्तिक आलोचना को ठोस दार्शनिक आधार दिया, रस की अलौकिकता का निषेध किया, जीवन और साहित्य के भावों में बुनियादी अन्तर स्वीकार नहीं किया, भावों को उनके आधार से अलग करके देखा, लोक-हृदय में लीन होने की दशा को रसदशा माना, रीति-ग्रंन्थों और उनकी सीमा में बंधे समीक्षकों का विरोध किया, ‘प्रेम’ की अपेक्षा ‘करुणा’ को अधिक महत्त्व दिया और लोक-रक्षा के विधान में उसकी महत्त्वपूर्ण भूमिका को पहचाना, साम्राज्यवादी उत्पीड़न का विरोध किया, अंग्रेजी साहित्य की व्यक्तिवादी एवं प्रगतिविरोधी प्रवृत्तियों से हिन्दी लेखकों को सावधान किया, काव्य में करुणा-प्रेरित प्रचण्ड भावों (क्रोध आदि) के विधान में भी सौन्दर्य देखा, परोक्ष सत्ता के प्रति प्रेम की अभिव्यक्ति करने वाले साम्प्रदायिक रहस्यवाद का विरोध किया, वस्तुओं और विचारों की गतिशीलता पर बल देते हुए सौन्दर्य एवं मंगल के गत्यात्मक स्वरूप को सहारा और इतिहास के अध्ययन की एक व्यवस्थित पद्धति कायम की।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उसकी एक विशेषता जीवन का संचित अनुभव प्रकट करने वाली वाक्यावली है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उनकी निर्भीकता, दृढ़ता, गहन अध्यवसाय और आत्मविश्वास के गुण उनके काव्य-सिद्धान्तों और साहित्यलोचन की ही तरह हिन्दी-प्रेमियों के लिए शिक्षाप्रद और प्रेरणा दायक है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "हिंदी के महान कथाकारों को चीरहरण से फुरसत न मिली, वह अंतस्तल की निगूढ़ भावनाओं का चित्रण करने में हिंदुस्तान की जनता का दुख-दर्द भूल गए।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "तुलसीदास के बाद हिंदी में यह पहला इतना बड़ा कलाकार पैदा हुआ था जिसकी रचनाएँ अपनी ही भाषा के क्षेत्र में नहीं, सुदूर दक्षिण के गाँवों में भी पहुँच गई थी।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "प्रेमचन्द से जिस चीज़ को हिन्दी के इन दिग्गज आलोचकों और कलाकारों ने नहीं सीखा, वह यह कि जनता कला का स्रोत है और उससे अलग रहकर महान साहित्य की रचना नहीं की जा सकती।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "प्रेमचंद ने ‘चंद्रकांता’ के पाठकों को अपनी तरफ ही नहीं खींचा, ‘चंद्रकांता’ में अरुचि भी पैदा की, जन-रूचि के लिए उन्होंने नए मापदंड कायम किए और साहित्य के नए पाठक और पाठिकाएँ भी पैदा किए।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "यह उनकी जबरदस्त सफलता थी।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "सर्वतोन्मुखी क्रांति का यह समर्थक अमल में हमेशा समझौता करता है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "‘गोदान’ की मूल समस्या ऋण की समस्या है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "इस उपन्यास में किसानों के साथ मानों वह आपबीती भी कह रहे थे।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "निराला की रचना-प्रक्रिया का स्रोत है उनका भावबोध।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "यह भावबोध उनकी विचारधारा से सम्बद्ध है किन्तु उसका प्रतिबिम्ब नहीं है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "निराला का स्वाधीनता-प्रेम उनके साहित्य में अप्रत्याशित नये-नये रूपों में व्यक्त होता है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "नये मानवतावाद के प्रतिष्ठापक निराला के साहित्य में मनुष्य वीर, क्रान्तिकारी योद्धा, कवि, निरन्तर संघर्षशील साथ ही अन्तर्द्वन्द्व, ग्लानि और पराजय से पीड़ित साधारण मनुष्य भी है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "निराला सौन्दर्य और उल्लास के कवि है, दुःख और मृत्यु के भी।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "रत्नावली के शब्दों में तुलसीदास को नहीं, वरन् साहित्य और संस्कृति की समस्त रीतिकालीन परम्परा को धिक्कारा गया है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उसके योगिनी रूप में मध्यकालीन नारी का नायिका-भेद वाला रूप जलकर भस्म हो गया है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "मुक्तिबोध का साहित्य उस व्यक्ति का साहित्य है जो जीवन की अनिवार्य विवशताओं के बीच निरन्तर अपने विवेक के अनुसार व्यक्तित्व के निर्माण में प्रयत्नशील रहता है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "शमशेर का काव्य रीतिवादी रूमानी सौर्न्यबोध और मार्क्सवादी विवेक के द्वन्द्व का काव्य है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "शमशेर में ऐसी कोई उलझन नहीं है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "शमशेर सजीले जिस्म के गुणगाने पर ऐसा रीझते हैं कि अँधेरे कुएँ या बाबड़ी में उतरने की उन्हें फुर्सत नहीं मिलती।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "किन्तु शमशेर उतने आत्ममुग्ध नहीं जितने ‘मुक्तिबोध’ थे।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उनका आत्म-संघर्ष है उत्तर छायावादी काव्यबोध को लेकर।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "जब समाजवादी दलों का बिखराव दूर होगा, जब हिन्दी प्रदेश की श्रमिक जनता एकजुट होकर नये समाज के निमार्ण की ओर बढ़ेगी, जब नयी कविता का अस्तित्वादी सैलाब सूख चुका होगाा, जब मध्यवर्ग और किसानों और मजदूरों में भी जन्म लेने वाले कवि दृढ़ता से अपना सम्बन्ध जन आन्दोलन से कायम करेंगे तब उनके सामने लोकप्रिय साहित्य और कलात्मक सौन्दर्य के सन्तुलन की समस्या फिर से पेश होगी", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उसमें दृढ़ क्रान्ति-भावना विद्यमान है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "वह लोक-संस्कृति के निकट है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उस में प्रखर राजनीतिक चेतना और गहरा व्यंग्य है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "उसमें यथार्थ जीवन के वैविध्यपूर्ण मार्मिक चित्र है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "मेरी पुस्तक 'भाषा और समाज' में जिन सिद्धान्तों का प्रतिपादन है, उनका यहाँ संवर्धन और विस्तार है, उनमें कहीं मौलिक परिवर्तन करना आवश्कयक प्रतीत नहीं हुआ।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "जिस विवेचन में अटल नियमों की अस्वीकृति हो, उसमें किसी भी स्थापना के लिए पूर्ण सत्य का दावा करना हास्यास्पद होगा।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "व्यक्तिवादी विचारधारा क्षीण होकर निर्जीव, विकृत, अस्वस्थ, यथार्थ विरोधी रचनाओं की सृष्टि कर रही है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "यथार्थवादी विचारधारा मनुष्य के सर्वांगीण विकास के उद्देश्य से ऐसी रचनाएँ करने की ओर प्रवृत्त है जिससे हमारी सामाजिक चेतना प्रखर हो।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "आधुनिक हिन्दी साहित्य की मूल धारा भी हमें इसी ओर बढ़ने की प्ररणा देती है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "कविता में तरह-तरह के प्रयोग करने की बडी गुंजाईश है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "नई कविता और आधुनिक हिन्दी कविता एक ही वस्तु नहीं है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "आलोचना का कोलाहल शांत होने पर नई कविता के कर्दम पर यथार्थवाद की निर्मल धारा बहती दिखाई देगी।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "आज के अनेक प्रसिद्ध लेखक झकोले खा रहे हैं, आस्था-अनास्था की समस्याओं से व्यथित हो उठते हैं, प्रत्येक राजनीतिक पार्टी से विश्वास उठ जाने की बातें करते हैं।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "यदि लेखक को इस जनता में आस्था हो, वह उसके साथ आगे बढ़ने को तैयार हो तो उसका झकोले खाना बंद हो जाए।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "प्रेमचंद की परंपरा में अनेक लेखक हैं।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "वे “आज भी हमारे गुरु हैं।”", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "भाषाई विवेचन एक कौशल है, यह कौशल यंत्रवत निश्चित किया जा सकता है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "टेकनोलाऑजी स्वयं विज्ञान नहीं है, वैसे ही भाषाई विवेचन का कौशल भाषा विज्ञान नहीं है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "प्रत्येक विज्ञान में अनुसंधानकर्त्ता का संवेदनशील होना उस विज्ञान के विकास की पहली शर्त है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "भाषा विज्ञान के विकास के लिए यह संवदेनशीलता और भी आवश्यक है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "कला के लिए कला, जैसे यह सिद्धान्त अमान्य है, वैसे ही कौशल के लिए कौशल-यह सिद्धान्त भी अमान्य है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "कश्मीर से लेकर तमिलनाडु तक, बंगाल से लेकर गुजरात तक राष्ट्रीय स्वाधीनता आन्दोलन ने एक भावना-सूत्र में देश की सभी जातियों और भाषाओं को बाँध दिया था।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "बहुजातीय राष्ट्रीयता का पाठ हमें अंग्रेजों ने नहीं पढ़ाया।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "हमारी राष्ट्रीयता जिस में तमिल, कश्मीरी, सिंधी आदि फलती-फूलती हैं।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "हमारी बहुजातीय राष्ट्रीयता की नींव अंग्रेजी राज कायम होने से पहले डाली गई थि।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "मानव जाति समस्त धरती पर फैली हुई है, समस्त काल में उसका प्रसार है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "इस मानव समाज को आपस में बाँधनेवाला कौन है? वह कवि है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "कवि उसे बाँधता है भाव और ज्ञान के द्वारा।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "कविता के लिए भावशक्ति और ज्ञानशक्ति का संयोग दरकार है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "जिसे रोमांटिसिज्म (छायावाद, स्वच्छन्दतावाद) कहा जाता है, वह अनेक प्रकार का था।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "कभी-कभी एक ही कवि में कई तरह का रोमांटिसिज्म देखने को मिलता है।", Author = "रामविलास शर्मा" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/रामविलास_शर्मा", Text = "बायरन ने इससे बहुत-सी बातें सीखीं किंतु अपने युग के अनुरुप उन्होंने व्यंग्य कविता को नई दिशा में मोड़ा।", Author = "रामविलास शर्मा" },
        };
    }
}